        }
        default:
          results.push(evaluatorResult(spec.type, false, 0, { error: `unknown evaluator type: ${spec.type}` }));
          break;
      }
    }
  } finally {
    if (pinnedWorkspaceRoot) fs.rmSync(pinnedWorkspaceRoot, { recursive: true, force: true });
  }
  return results;
}

